<template>
  <section class="purchase-create-page" v-loading="loading">
    <div class="page-heading"><div><p class="page-breadcrumb">采购管理 / 新增采购订单</p><h1 class="page-title">新增采购订单</h1><p class="page-desc">录入采购主单，并可在保存前维护采购明细和付款计划。</p></div><div class="page-actions"><el-button @click="router.push('/purchases')">返回采购列表</el-button></div></div>
    <el-form ref="formRef" :model="form" :rules="rules" label-position="left" label-width="106px">
      <section class="content-panel detail-section"><div class="detail-title"><span>01</span><div><strong>采购基础信息</strong><small>供应商、关联订单和日期</small></div></div><div class="grid3">
        <el-form-item label="采购单号" prop="poNo"><el-input v-model="form.poNo" readonly class="auto-code-input" placeholder="系统自动生成采购单号"><template #append><el-button :loading="codeGenerating" @click="fillPoNo">自动生成</el-button></template></el-input></el-form-item>
        <el-form-item label="供应商" prop="supplierId"><el-select v-model="form.supplierId" filterable style="width:100%"><el-option v-for="item in supplierOptions" :key="item.id" :label="optionLabel('suppliers',item)" :value="item.id" /></el-select></el-form-item>
        <el-form-item label="关联销售单"><el-select v-model="form.orderId" filterable clearable style="width:100%"><el-option v-for="item in salesOrders" :key="item.id" :label="item.orderNo" :value="item.id" /></el-select></el-form-item>
        <el-form-item label="归属部门"><el-select v-model="form.deptId" filterable style="width:100%"><el-option v-for="item in deptOptions" :key="item.id" :label="optionLabel('depts',item)" :value="item.id" /></el-select></el-form-item>
        <el-form-item label="采购类型"><el-select v-model="form.poType" style="width:100%"><el-option v-for="item in purchaseTypeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item>
        <el-form-item label="采购员"><el-select v-model="form.buyerId" filterable clearable style="width:100%"><el-option v-for="item in staffOptions" :key="item.id" :label="optionLabel('staffs',item)" :value="item.id" /></el-select></el-form-item>
        <el-form-item label="采购日期" prop="poDate"><el-date-picker v-model="form.poDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item>
        <el-form-item label="预计到货"><el-date-picker v-model="form.expectArriveDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item>
        <el-form-item label="汇总入库单号"><el-input v-model="form.stockInNo" /></el-form-item>
      </div></section>
      <section class="content-panel detail-section"><div class="detail-title"><span>02</span><div><strong>金额与到货控制</strong><small>采购数量、金额和状态</small></div></div><div class="grid3">
        <el-form-item label="采购数量"><el-input-number v-model="form.qtyTotal" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="采购金额"><el-input-number v-model="form.amount" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="税率"><el-input-number v-model="form.taxRate" :min="0" :max="1" :precision="4" style="width:100%" /></el-form-item>
        <el-form-item label="价税合计"><el-input-number v-model="form.amountTax" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="已到货数量"><el-input-number v-model="form.qtyReceived" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="采购状态"><el-select v-model="form.status" style="width:100%"><el-option v-for="item in purchaseStatusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item>
        <el-form-item label="备注" class="wide"><el-input v-model="form.remark" type="textarea" :rows="3" /></el-form-item>
      </div></section>
    </el-form>
    <section class="content-panel detail-section"><div class="section-heading"><div class="detail-title compact"><span>03</span><div><strong>采购明细</strong><small>保存采购订单时一起提交</small></div></div><el-button type="primary" plain @click="openItemCreate">新增采购明细</el-button></div>
      <el-table :data="draftItems" border empty-text="尚未新增采购明细"><el-table-column label="物料" min-width="180"><template #default="{row}">{{ materialLabel(row.materialId) }}</template></el-table-column><el-table-column prop="part" label="部位" width="90" /><el-table-column prop="unit" label="单位" width="70" /><el-table-column prop="qty" label="数量" width="90" /><el-table-column label="单价" width="100"><template #default="{row}">{{ money(row.price) }}</template></el-table-column><el-table-column label="金额" width="110"><template #default="{row}">{{ money(row.amount) }}</template></el-table-column><el-table-column prop="arriveDate" label="到货日期" width="110" /><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="openItemEdit(row)">编辑</el-button><el-button link type="danger" @click="removeItem(row)">删除</el-button></template></el-table-column></el-table>
    </section>
    <section class="content-panel detail-section"><div class="section-heading"><div class="detail-title compact"><span>04</span><div><strong>付款计划</strong><small>保存采购订单时一起提交并关联供应商</small></div></div><el-button type="primary" plain @click="openPlanCreate">新增付款计划</el-button></div>
      <el-table :data="draftPlans" border empty-text="尚未新增付款计划"><el-table-column prop="planNo" label="计划单号" width="150" /><el-table-column prop="seqNo" label="节点" width="70" /><el-table-column label="节点类型" width="120"><template #default="{row}">{{ optionText(planNodeOptions,row.nodeType) }}</template></el-table-column><el-table-column prop="planDate" label="计划日期" width="110" /><el-table-column label="计划金额" width="115"><template #default="{row}">{{ money(row.planAmount) }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{ optionText(planStatusOptions,row.status) }}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="openPlanEdit(row)">编辑</el-button><el-button link type="danger" @click="removePlan(row)">删除</el-button></template></el-table-column></el-table>
    </section>
    <section class="content-panel detail-section"><div class="detail-title"><span>05</span><div><strong>关联发票</strong><small>采购订单保存后可关联进项发票</small></div></div><el-empty description="采购订单保存后，可在详情页查看关联发票" :image-size="72" /></section>
    <div class="submit-bar"><el-button @click="router.push('/purchases')">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存采购订单及明细</el-button></div>

    <el-dialog v-model="itemDialog" :title="itemEditingKey?'编辑采购明细':'新增采购明细'" width="760px" destroy-on-close><el-form :model="itemForm" label-position="left" label-width="100px"><div class="grid2">
      <el-form-item label="物料"><el-select v-model="itemForm.materialId" filterable style="width:100%" @change="syncMaterialUnit"><el-option v-for="item in materialOptions" :key="item.id" :label="optionLabel('materials',item)" :value="item.id" /></el-select></el-form-item><el-form-item label="使用部位"><el-input v-model="itemForm.part" /></el-form-item><el-form-item label="单位"><el-input v-model="itemForm.unit" /></el-form-item><el-form-item label="数量"><el-input-number v-model="itemForm.qty" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="单价"><el-input-number v-model="itemForm.price" :min="0" :precision="4" style="width:100%" /></el-form-item><el-form-item label="金额"><el-input-number v-model="itemForm.amount" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="到货日期"><el-date-picker v-model="itemForm.arriveDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="itemForm.remark" type="textarea" :rows="2" /></el-form-item>
    </div></el-form><template #footer><el-button @click="itemDialog=false">取消</el-button><el-button type="primary" @click="saveDraftItem">确定</el-button></template></el-dialog>

    <el-dialog v-model="planDialog" :title="planEditingKey?'编辑付款计划':'新增付款计划'" width="720px" destroy-on-close><el-form :model="planForm" label-position="left" label-width="110px"><div class="grid2">
      <el-form-item label="计划单号"><el-input v-model="planForm.planNo" /></el-form-item><el-form-item label="节点序号"><el-input-number v-model="planForm.seqNo" :min="1" style="width:100%" /></el-form-item><el-form-item label="节点类型"><el-select v-model="planForm.nodeType" style="width:100%"><el-option v-for="item in planNodeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="计划日期"><el-date-picker v-model="planForm.planDate" type="date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="计划金额"><el-input-number v-model="planForm.planAmount" :min="0" :precision="2" style="width:100%" /></el-form-item><el-form-item label="状态"><el-select v-model="planForm.status" style="width:100%"><el-option v-for="item in planStatusOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="planForm.remark" type="textarea" :rows="2" /></el-form-item>
    </div></el-form><template #footer><el-button @click="planDialog=false">取消</el-button><el-button type="primary" @click="saveDraftPlan">确定</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import { onMounted,reactive,ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { createOne } from '../api/crud'
import { generateCode } from '../api/codeRules'
import { loadLookupData,lookupDefinitions } from '../api/lookups'
import { createPurchaseItem,createPurchasePlan } from '../api/purchaseDetail'
const router=useRouter(),loading=ref(false),saving=ref(false),codeGenerating=ref(false),formRef=ref(null)
const supplierOptions=ref([]),staffOptions=ref([]),deptOptions=ref([]),materialOptions=ref([]),salesOrders=ref([]),draftItems=ref([]),draftPlans=ref([])
const itemDialog=ref(false),planDialog=ref(false),itemEditingKey=ref(null),planEditingKey=ref(null),itemForm=reactive({}),planForm=reactive({});let seq=1
const purchaseTypeOptions=[{label:'面料',value:1},{label:'辅料',value:2},{label:'包装',value:3},{label:'外协',value:4}]
const purchaseStatusOptions=[{label:'待审',value:1},{label:'已审',value:2},{label:'部分到货',value:3},{label:'已到货',value:4},{label:'已入库',value:5},{label:'取消',value:6}]
const planNodeOptions=[{label:'预付款',value:1},{label:'到货款',value:2},{label:'尾款',value:3},{label:'补款',value:4},{label:'质保金',value:5},{label:'其他',value:6}]
const planStatusOptions=[{label:'未付',value:0},{label:'部分',value:1},{label:'已结清',value:2},{label:'逾期',value:3}]
const today=()=>new Date().toLocaleDateString('sv-SE')
const form=reactive({poNo:'',supplierId:null,orderId:null,deptId:null,buyerId:null,poType:1,poDate:today(),expectArriveDate:null,qtyTotal:0,amount:0,taxRate:0.13,amountTax:0,qtyReceived:0,status:1,stockInNo:'',remark:''})
const rules={poNo:[{required:true,message:'请输入采购单号',trigger:'blur'}],supplierId:[{required:true,message:'请选择供应商',trigger:'change'}],poDate:[{required:true,message:'请选择采购日期',trigger:'change'}]}
const optionLabel=(k,i)=>lookupDefinitions[k].label(i);const optionText=(opts,v)=>opts.find(x=>x.value===v)?.label||v;const money=v=>v==null?'—':'¥'+Number(v).toFixed(2)
const materialLabel=id=>{const x=materialOptions.value.find(i=>Number(i.id)===Number(id));return x?optionLabel('materials',x):'—'}
const supplierLabel=id=>{const x=supplierOptions.value.find(i=>Number(i.id)===Number(id));return x?optionLabel('suppliers',x):''}
onMounted(async()=>{loading.value=true;try{const [sup,staff,dept,mat,orders]=await Promise.all([loadLookupData('suppliers'),loadLookupData('staffs'),loadLookupData('depts'),loadLookupData('materials'),loadLookupData('orders')]);supplierOptions.value=sup;staffOptions.value=staff;deptOptions.value=dept;materialOptions.value=mat;salesOrders.value=orders}catch(e){ElMessage.error(e?.message||'加载关联数据失败')}finally{loading.value=false}})
async function fillPoNo(){if(codeGenerating.value)return;codeGenerating.value=true;try{const r=await generateCode('PURCHASE');form.poNo=r.data.data.previewCode;ElMessage.success('已生成采购单号：'+form.poNo)}catch(e){ElMessage.error(e?.response?.data?.message||'生成采购单号失败')}finally{codeGenerating.value=false}}
function openItemCreate(){itemEditingKey.value=null;Object.keys(itemForm).forEach(k=>delete itemForm[k]);Object.assign(itemForm,{_key:'item-'+seq++,materialId:null,part:'整件',unit:'米',qty:0,price:0,amount:0,qtyReceived:0,arriveDate:'',remark:''});itemDialog.value=true}
function openItemEdit(row){itemEditingKey.value=row._key;Object.keys(itemForm).forEach(k=>delete itemForm[k]);Object.assign(itemForm,row);itemDialog.value=true}
function syncMaterialUnit(id){const x=materialOptions.value.find(i=>Number(i.id)===Number(id));if(x)itemForm.unit=x.unit||itemForm.unit}
function saveDraftItem(){if(!itemForm.materialId){ElMessage.warning('请选择物料');return}const c=JSON.parse(JSON.stringify(itemForm));const i=draftItems.value.findIndex(x=>x._key===itemEditingKey.value);if(i>=0)draftItems.value[i]=c;else draftItems.value.push(c);itemDialog.value=false}
function removeItem(row){draftItems.value=draftItems.value.filter(x=>x._key!==row._key)}
function openPlanCreate(){planEditingKey.value=null;Object.keys(planForm).forEach(k=>delete planForm[k]);Object.assign(planForm,{_key:'plan-'+seq++,planNo:'',seqNo:draftPlans.value.length+1,nodeType:1,planDate:'',planAmount:0,status:0,remark:''});planDialog.value=true}
function openPlanEdit(row){planEditingKey.value=row._key;Object.keys(planForm).forEach(k=>delete planForm[k]);Object.assign(planForm,row);planDialog.value=true}
function saveDraftPlan(){if(!planForm.planNo||!planForm.planDate){ElMessage.warning('请填写计划单号和计划日期');return}const c=JSON.parse(JSON.stringify(planForm));const i=draftPlans.value.findIndex(x=>x._key===planEditingKey.value);if(i>=0)draftPlans.value[i]=c;else draftPlans.value.push(c);planDialog.value=false}
function removePlan(row){draftPlans.value=draftPlans.value.filter(x=>x._key!==row._key)}
async function save(){if(!form.poNo)await fillPoNo();if(!form.poNo)return;const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;saving.value=true;try{const r=await createOne('/pu/orders',form);if(r.data?.code!==0)throw new Error(r.data?.message||'保存失败');const poId=r.data.data.id,poNo=r.data.data.poNo||form.poNo;const results=await Promise.allSettled([...draftItems.value.map(x=>{const {_key,...d}=x;return createPurchaseItem({...d,poId,deptId:form.deptId})}),...draftPlans.value.map(x=>{const {_key,...d}=x;return createPurchasePlan({...d,deptId:form.deptId,direction:2,sourceType:2,sourceId:poId,sourceNo:poNo,partnerType:2,partnerId:form.supplierId,partnerName:supplierLabel(form.supplierId),paidAmount:0})})]);const failed=results.filter(x=>x.status==='rejected').length;if(failed)ElMessage.warning('采购单已保存，但有 '+failed+' 条明细或付款计划提交失败');else ElMessage.success('采购订单、明细和付款计划已保存');await router.push('/purchases/'+poId)}catch(e){ElMessage.error(e?.response?.data?.message||e?.message||'保存采购订单失败')}finally{saving.value=false}}
</script>

<style scoped>
.page-breadcrumb{margin:0 0 7px;color:#2b6cb0;font-size:12px}.detail-section{margin-bottom:14px}.detail-title{display:flex;align-items:center;gap:12px;margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid #edf0f4}.detail-title>span{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:#eaf2fb;color:#2b6cb0;font-size:11px;font-weight:700}.detail-title strong{display:block;color:#1f3a5f;font-size:15px}.detail-title small{display:block;margin-top:3px;color:#98a2b3;font-size:11px}.detail-title.compact{margin:0;padding:0;border:0}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.grid3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 18px}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px;max-height:60vh;overflow-y:auto}.wide{grid-column:1/-1}.grid3 :deep(.el-form-item__label),.grid2 :deep(.el-form-item__label){justify-content:flex-start}.submit-bar{position:sticky;bottom:0;z-index:2;display:flex;justify-content:flex-end;gap:9px;padding:13px 16px;border:1px solid #e4e7ed;border-radius:8px;background:rgba(255,255,255,.96);box-shadow:0 -4px 16px rgba(31,58,95,.08)}@media(max-width:1050px){.grid3{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.grid3,.grid2{grid-template-columns:1fr}}
</style>
